-- Retire legacy execution; preserve historical batches, rules, values and archives.

UPDATE metric_import_config SET enabled=0 WHERE enabled<>0;

UPDATE collection_source SET enabled=0, config_json=JSON_SET(config_json,'$.enabled',JSON_EXTRACT('false','$')) WHERE enabled<>0;

INSERT INTO collection_source(code,name,config_json,enabled,next_scan_at)
SELECT 'business_value','业务价值脚本采集','{"code":"business_value","name":"业务价值脚本采集","parser":"python-worker","format":"csv","filePattern":"*.csv","enabled":false,"importPath":"raw_data/import/scripts/business_value","archivePath":"raw_data/archive/scripts/business_value","intervalSeconds":300,"settleSeconds":30,"dateMode":"data_time","dateRegex":null,"dateFormat":null,"sheet":"","delimiter":",","encoding":"UTF-8","fields":[{"source":"指标编码","target":"metric_code","type":"string","required":true},{"source":"指标名称","target":"metric_name","type":"string","required":false},{"source":"指标值","target":"metric_value","type":"decimal","required":false},{"source":"单位","target":"unit","type":"string","required":false},{"source":"数据时间","target":"data_time","type":"datetime","required":true},{"source":"指标大类","target":"category_name","type":"string","required":false},{"source":"指标小类","target":"sub_category_name","type":"string","required":false}],"worker":{"version":"business_value-20261027-001","categoryCode":"businessValue","timeoutSeconds":60}}',0,NOW() FROM metric_category WHERE category_code='businessValue'
ON DUPLICATE KEY UPDATE name=VALUES(name),
 config_json=JSON_SET(VALUES(config_json),'$.archivePath',COALESCE(JSON_UNQUOTE(JSON_EXTRACT(config_json,'$.archivePath')),'raw_data/archive/scripts/business_value')),
 enabled=0,next_scan_at=NOW(),last_error=NULL;

